<script setup>
import { ref, computed, watch, onMounted, onBeforeUnmount } from 'vue'
import Icon from './components/Icon.vue'
import BoardScene from './components/BoardScene.vue'
import DiagnosticPanel from './components/DiagnosticPanel.vue'
import LessonModal from './components/LessonModal.vue'
import { getComponents, lessons, glossary, sources } from './data.js'
import { sequenceFor } from './simulation.js'

const view=ref('lab'),device=ref('laptop'),selected=ref('cpu'),infoTab=ref('function'),labels=ref(true)
const scene=ref(null),search=ref(''),searchInput=ref(null),libraryFilter=ref('Todos'),glossarySearch=ref('')
const activeLesson=ref(null),mobileMenu=ref(false),settings=ref(null),confirmReset=ref(false),toast=ref('')
const completed=ref([]),solved=ref([]),reducedMotion=ref(false),storageAvailable=ref(true)
const step=ref(-1),playing=ref(false),diagnosticPower=ref(false),diagnosticCase=ref('no-power')
let timer,toastTimer
const nav=[{id:'lab',name:'Laboratorio',icon:'LayoutDashboard'},{id:'lessons',name:'Ruta de aprendizaje',icon:'BookOpen'},{id:'library',name:'Componentes',icon:'Cpu'},{id:'diagnostics',name:'Diagnóstico',icon:'ScanSearch'},{id:'glossary',name:'Glosario técnico',icon:'BookA'}]
const parts=computed(()=>getComponents(device.value))
const component=computed(()=>parts.value.find(c=>c.id===selected.value)||parts.value[0])
const seq=computed(()=>sequenceFor(device.value))
const progress=computed(()=>Math.round(completed.value.length/lessons.length*100))
const nextLesson=computed(()=>lessons.find(l=>!completed.value.includes(l.id))||lessons[0])
const title=computed(()=>({lab:'Entiende la placa. Encuentra la falla.',diagnostics:'Observa. Mide. Encuentra la causa.',lessons:'De la curiosidad al diagnóstico.',library:'Conoce las piezas del sistema.',glossary:'El lenguaje de la reparación.'})[view.value])
const subtitle=computed(()=>({lab:'Explora cada componente y descubre cómo todo trabaja en conjunto.',diagnostics:'Practica con fallas guiadas y aprende a respaldar tus hipótesis.',lessons:'Seis lecciones para construir una forma de pensar, paso a paso.',library:'Cada componente tiene una función. Aprende a reconocerla.',glossary:'Conceptos claros para entender lo que sucede en una placa.'})[view.value])
const filteredParts=computed(()=>parts.value.filter(c=>(libraryFilter.value==='Todos'||c.category===libraryFilter.value)))
const categories=computed(()=>['Todos',...new Set(parts.value.map(c=>c.category))])
const matchingParts=computed(()=>search.value.trim()?parts.value.filter(c=>`${c.name} ${c.short} ${c.category}`.toLowerCase().includes(search.value.toLowerCase())).slice(0,6):[])
const matchingTerms=computed(()=>glossary.filter(([term,definition])=>`${term} ${definition}`.toLowerCase().includes(glossarySearch.value.toLowerCase())))
const sceneStep=computed(()=>view.value==='diagnostics'?(diagnosticPower.value?(diagnosticCase.value==='no-power'?0:diagnosticCase.value==='no-display'?3:5):-1):step.value)

function notify(message){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',4800)}
function save(){try{localStorage.setItem('placa-lab:v1',JSON.stringify({completed:completed.value,solved:solved.value,reducedMotion:reducedMotion.value}))}catch{storageAvailable.value=false}}
function navigate(id){view.value=id;mobileMenu.value=false;search.value='';stop();step.value=-1;diagnosticPower.value=false;window.scrollTo(0,0)}
function selectPart(id){selected.value=id;infoTab.value='function'}
function searchSelect(id){navigate('lab');selectPart(id)}
function setDevice(value){if(device.value===value)return;stop();step.value=-1;device.value=value;if(!getComponents(value).some(c=>c.id===selected.value))selected.value='cpu';libraryFilter.value='Todos'}
function stop(){clearInterval(timer);playing.value=false}
function play(){
  if(playing.value){stop();return}
  if(step.value>=5)step.value=-1
  playing.value=true
  advance()
  if(playing.value)timer=setInterval(advance,2600)
}
function advance(){if(step.value>=5){stop();return}step.value++;selected.value=seq.value[step.value].id;if(step.value===5)stop()}
function goStep(i){stop();step.value=i;selected.value=seq.value[i].id}
function completeLesson(id){if(!completed.value.includes(id)){completed.value.push(id);save();notify('Una idea más clara. Lección completada.')}}
function exploreLesson(lesson){activeLesson.value=null;navigate(['meter','faults','method'].includes(lesson.id)?'diagnostics':'lab');selectPart(lesson.focus);if(lesson.id==='power')play()}
function solveCase(id){if(!solved.value.includes(id)){solved.value.push(id);save();notify('Caso resuelto. Tu diagnóstico tiene evidencia.')}}
function resetProgress(){completed.value=[];solved.value=[];save();confirmReset.value=false;notify('Tu progreso se ha reiniciado.')}
function keydown(e){if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();searchInput.value?.focus()}if(e.key==='Escape'){search.value='';mobileMenu.value=false}}
watch(reducedMotion,save)
onMounted(()=>{
  try{const stored=JSON.parse(localStorage.getItem('placa-lab:v1')||'{}');completed.value=Array.isArray(stored.completed)?[...new Set(stored.completed.filter(id=>lessons.some(l=>l.id===id)))]:[];solved.value=Array.isArray(stored.solved)?[...new Set(stored.solved.filter(id=>['no-power','no-display'].includes(id)))]:[];reducedMotion.value=stored.reducedMotion??window.matchMedia('(prefers-reduced-motion: reduce)').matches}catch{storageAvailable.value=false}
  document.addEventListener('keydown',keydown)
})
onBeforeUnmount(()=>{stop();clearTimeout(toastTimer);document.removeEventListener('keydown',keydown)})
</script>

<template>
  <div class="app-shell" :class="{'reduce-motion':reducedMotion}">
    <a class="skip-link" href="#main">Saltar al contenido</a>
    <button v-if="mobileMenu" class="sidebar-backdrop" aria-label="Cerrar menú" @click="mobileMenu=false"></button>
    <aside class="sidebar" :class="{open:mobileMenu}">
      <a class="brand" aria-label="Placa Lab · Inicio" href="#" @click.prevent="navigate('lab')"><div class="brand-symbol"><Icon name="CircuitBoard" :size="28" /></div><span>placa<span class="brand-light">lab</span><small>EL CONOCIMIENTO CONECTA.</small></span></a>
      <div class="sidebar-section-label">TU BANCO DE TRABAJO</div>
      <nav aria-label="Navegación principal"><button v-for="item in nav" :key="item.id" class="nav-item" :aria-label="item.name" :class="{active:view===item.id}" :aria-current="view===item.id?'page':undefined" @click="navigate(item.id)"><Icon :name="item.icon" :size="19" /><span>{{ item.name }}</span><span v-if="item.id==='diagnostics'" class="nav-count">02</span><span v-if="view===item.id" class="nav-active-dot"></span></button></nav>
      <div class="sidebar-course"><div class="course-top"><span class="tiny-dot"></span> APRENDER HACIENDO</div><div class="course-art"><Icon name="Sprout" :size="35" /><span class="art-orbit"></span></div><h3>Un componente.<br>Un descubrimiento.</h3><p>No necesitas saberlo todo.<br>Solo empezar por una conexión.</p><button @click="activeLesson=nextLesson">{{ completed.length?'Continuar aprendiendo':'Comienza tu recorrido' }} <Icon name="ArrowUpRight" :size="17" /></button></div>
      <div class="sidebar-bottom"><button @click="settings.showModal()"><Icon name="Settings2" :size="18" /> Preferencias</button><div class="language"><Icon name="Globe2" :size="16" /><span>Español</span><span>ES</span></div><div class="sidebar-signoff"><span class="status-dot"></span> Hecho para mentes curiosas <span>↗</span></div></div>
    </aside>

    <div class="main-shell">
      <header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu-button" aria-label="Abrir menú" @click="mobileMenu=true"><Icon name="Menu" /></button><span>Tu espacio para aprender</span><Icon name="ChevronRight" :size="14" /><strong>{{ nav.find(n=>n.id===view)?.name }}</strong></div><div class="topbar-right"><div class="search-wrap"><Icon name="Search" :size="16" /><input ref="searchInput" v-model="search" placeholder="Buscar un componente…" aria-label="Buscar componentes" autocomplete="off" /><kbd>/</kbd><div v-if="search.trim()" class="search-results"><button v-for="c in matchingParts" :key="c.id" @click="searchSelect(c.id)"><Icon :name="c.icon" :size="18" /><span>{{ c.name }}<small>{{ c.category }}</small></span><Icon name="ArrowUpRight" :size="15" /></button><p v-if="!matchingParts.length">No hay coincidencias. Prueba “RAM” o “energía”.</p></div></div><button class="profile-button" @click="navigate('lessons')" aria-label="Ver mi aprendizaje">A<span></span></button></div></header>
      <main id="main" class="main-content">
        <section class="page-heading"><div><div class="eyebrow"><span class="eyebrow-line"></span> {{ view==='diagnostics'?'APRENDE A DIAGNOSTICAR':'EXPLORA. ENTIENDE. REPARA.' }}</div><h1>{{ title }}</h1><p>{{ subtitle }}</p></div><button class="progress-badge" @click="navigate('lessons')"><div class="progress-ring" :style="{'--progress':progress+'%'}"><Icon name="Sprout" :size="19" /></div><span><small>Tu aprendizaje</small><strong>{{ completed.length }} <span>/ {{ lessons.length }} lecciones</span></strong></span><Icon name="ChevronRight" :size="15" /></button></section>

        <template v-if="view==='lab'||view==='diagnostics'">
          <section class="lab-layout" :class="{'diagnostics-layout':view==='diagnostics'}" aria-label="Laboratorio interactivo">
            <div class="workbench">
              <div class="workbench-header"><div class="device-tabs" role="group" aria-label="Tipo de placa"><button :class="{active:device==='laptop'}" :aria-pressed="device==='laptop'" @click="setDevice('laptop')"><Icon name="Laptop" :size="17" /> Laptop</button><button :class="{active:device==='desktop'}" :aria-pressed="device==='desktop'" @click="setDevice('desktop')"><Icon name="Monitor" :size="17" /> PC de escritorio</button></div><span class="model-badge"><span class="tiny-dot"></span> MODELO 3D</span></div>
              <div class="board-stage"><div class="stage-caption"><span>01 / {{ device==='laptop'?'LAPTOP':'DESKTOP' }}</span><strong>{{ device==='laptop'?'Anatomía de una laptop':'Anatomía de una PC' }}</strong><small>Placa didáctica · {{ parts.length }} componentes</small></div><div class="stage-coordinates" aria-hidden="true"><span>Y</span><div>↖<span>↑</span>↗</div><span>X &nbsp;&nbsp;&nbsp; Z</span></div><BoardScene ref="scene" :device="device" :selected="selected" :labels="labels" :step="sceneStep" :running="playing" :reduced-motion="reducedMotion" @select="selectPart" /><div class="stage-hint"><Icon name="MousePointer2" :size="13" /><span>Arrastra para girar · Selecciona para descubrir</span></div><div class="scene-tools"><button class="icon-button" @click="scene?.zoom(1)" aria-label="Acercar placa" title="Acercar"><Icon name="Plus" :size="17" /></button><button class="icon-button" @click="scene?.zoom(-1)" aria-label="Alejar placa" title="Alejar"><Icon name="Minus" :size="17" /></button><span></span><button class="icon-button" @click="scene?.rotate()" aria-label="Girar placa 45 grados" title="Girar"><Icon name="Rotate3d" :size="18" /></button><button class="icon-button" @click="scene?.reset()" aria-label="Restablecer vista" title="Restablecer vista"><Icon name="Scan" :size="17" /></button><span></span><button class="icon-button" :class="{active:labels}" :aria-pressed="labels" @click="labels=!labels" aria-label="Mostrar etiquetas" title="Etiquetas"><Icon name="Tags" :size="17" /></button></div><div class="stage-scale" aria-hidden="true">MODELO CONCEPTUAL <span></span></div></div>
              <div class="workbench-footer"><div class="live-state"><span class="status-dot" :class="{powered:sceneStep>=0}"></span><span>{{ view==='diagnostics'?(diagnosticPower?'Placa alimentada · simulación':'Placa desconectada'):step<0?'Lista para explorar':step===5?'Secuencia completada':playing?'Encendido en curso':'Secuencia en pausa' }}</span></div><button v-if="view==='lab'" class="power-button" @click="play"><Icon :name="playing?'Pause':'Play'" :size="15" />{{ playing?'Pausar':step>=0&&step<5?'Continuar encendido':'Ver encendido' }}<Icon name="ArrowRight" :size="15" /></button><span v-else class="footer-tag">MEDICIONES VIRTUALES</span></div>
              <div v-if="view==='lab'&&step>=0" class="sequence-panel"><div class="sequence-steps"><button v-for="(s,i) in seq" :key="s.id" :class="{done:i<step,current:i===step}" @click="goStep(i)"><span>{{ i<step?'✓':String(i+1).padStart(2,'0') }}</span>{{ s.label }}</button></div><p><strong>{{ seq[step].value }}</strong>{{ seq[step].text }}<button @click="stop();step=-1" aria-label="Cerrar secuencia"><Icon name="X" :size="15" /></button></p></div>
            </div>

            <aside v-if="view==='lab'" class="component-panel"><div class="panel-eyebrow"><span class="tiny-dot orange"></span> EXPLORADOR DE COMPONENTES <span>{{ component.ref }}</span></div><div class="component-title"><div class="component-icon"><Icon :name="component.icon" :size="32" /></div><span class="component-category">{{ component.category }}</span></div><h2>{{ component.name }}</h2><p class="component-tagline">{{ component.summary }}</p><div class="info-tabs" role="tablist" aria-label="Información del componente"><button v-for="t in [{id:'function',name:'Función'},{id:'signals',name:'Señales'},{id:'faults',name:'Fallas'}]" :key="t.id" role="tab" :aria-selected="infoTab===t.id" @click="infoTab=t.id" :class="{active:infoTab===t.id}">{{ t.name }}<Icon v-if="t.id==='faults'" name="ArrowUpRight" :size="13" /></button></div><div class="info-content" role="tabpanel"><template v-if="infoTab==='function'"><p>{{ component.description }}</p><div class="component-facts"><div><Icon name="MapPin" :size="17" /><span><small>DÓNDE ENCONTRARLO</small>{{ component.location }}</span></div><div><Icon name="Fingerprint" :size="17" /><span><small>CÓMO IDENTIFICARLO</small>Referencia habitual: <strong>{{ component.prefix }}</strong></span></div></div></template><template v-else-if="infoTab==='signals'"><p>{{ component.detail }}</p><div class="signal-card"><span>SEÑALES / LÍNEAS</span><strong>{{ component.signal }}</strong><span>ALIMENTACIÓN</span><p>{{ component.voltage }}</p></div><p class="help-text">Verifica siempre el esquema y la hoja de datos del componente real.</p></template><template v-else><p class="field-label">Síntomas que orientan</p><ul class="symptom-list"><li v-for="symptom in component.symptoms" :key="symptom"><span></span>{{ symptom }}</li></ul><p>{{ component.check }}</p></template><div class="technician-tip"><Icon name="Lightbulb" :size="19" /><div><strong>Piensa como técnico</strong><p>{{ component.tip }}</p></div></div></div><button class="panel-action" @click="navigate('diagnostics')"><Icon name="ScanSearch" :size="17" /> Llevarlo a la práctica <Icon name="ArrowUpRight" :size="17" /></button></aside>
            <aside v-else class="component-panel diagnostic-container"><DiagnosticPanel :device="device" @select="selectPart" @case-change="diagnosticCase=$event" @power-change="diagnosticPower=$event" @solved="solveCase" /></aside>
          </section>

          <div class="bench-note"><Icon name="Info" :size="14" /><span>Aprende con un modelo simplificado. La distribución, las tensiones y la secuencia varían entre equipos.</span><button @click="navigate('glossary')">Guía y referencias <Icon name="ArrowUpRight" :size="13" /></button></div>
          <section v-if="view==='lab'" class="learning-strip"><div class="section-heading"><div><span class="eyebrow">PEQUEÑOS PASOS, GRANDES CONEXIONES</span><h2>Tu próxima conexión.</h2></div><button class="text-link" @click="navigate('lessons')">Ver la ruta completa <Icon name="ArrowUpRight" :size="17" /></button></div><div class="lesson-strip-grid"><button v-for="(lesson,i) in lessons.slice(0,4)" :key="lesson.id" class="lesson-strip-card" :class="{featured:lesson.id===nextLesson.id,completed:completed.includes(lesson.id)}" @click="activeLesson=lesson"><span class="lesson-num">{{ String(i+1).padStart(2,'0') }}</span><div class="lesson-art"><Icon :name="lesson.icon" :size="30" /></div><span class="lesson-strip-name">{{ lesson.title }}<small><Icon name="Clock3" :size="11" /> {{ lesson.time }} min <span>·</span> {{ completed.includes(lesson.id)?'Completada':i===0?'Empieza aquí':'A tu ritmo' }}</small></span><Icon :name="completed.includes(lesson.id)?'CircleCheck':'ArrowUpRight'" :size="17" /></button></div></section>
          <section v-else class="diagnostic-guidance"><Icon name="NotebookPen" :size="24" /><div><h3>Un síntoma es una pista, no un diagnóstico.</h3><p>Inspecciona, compara y documenta. En hardware real, mide resistencia con adaptador y batería desconectados y sin energía residual. Esta práctica se limita a circuitos de baja tensión; no se abre una fuente de alimentación.</p></div><span>{{ solved.length }}/2 casos<br>resueltos</span></section>
        </template>

        <section v-else-if="view==='lessons'" class="learning-page"><div class="route-banner"><div><span class="eyebrow">TU RUTA · NIVEL INICIAL</span><h2>La reparación comienza<br>por entender.</h2><p>43 minutos de conceptos, exploración y práctica.<br>Sin prisa. Tu progreso se guarda en este navegador.</p><button class="button button-lime" @click="activeLesson=nextLesson">{{ completed.length?'Continúa tu recorrido':'Empezar por lo esencial' }}<Icon name="ArrowRight" :size="17" /></button></div><div class="route-illustration" aria-hidden="true"><span class="orbit one"></span><span class="orbit two"></span><Icon name="CircuitBoard" :size="110" /><span class="orbit-node n1"><Icon name="Zap" :size="25" /></span><span class="orbit-node n2"><Icon name="Search" :size="25" /></span><span class="orbit-node n3"><Icon name="Wrench" :size="25" /></span></div></div><div class="lesson-grid"><button v-for="(lesson,i) in lessons" :key="lesson.id" class="lesson-card" @click="activeLesson=lesson"><div class="lesson-card-top"><span class="lesson-card-icon"><Icon :name="lesson.icon" :size="27" /></span><span class="lesson-status" :class="{done:completed.includes(lesson.id)}"><Icon v-if="completed.includes(lesson.id)" name="CircleCheck" :size="13" />{{ completed.includes(lesson.id)?'Completada':`${lesson.time} min` }}</span></div><span class="eyebrow">LECCIÓN {{ String(i+1).padStart(2,'0') }}</span><h3>{{ lesson.title }}</h3><p>{{ lesson.subtitle }}</p><div class="lesson-card-bottom">{{ completed.includes(lesson.id)?'Volver a explorar':'Abrir lección' }} <Icon name="ArrowUpRight" :size="19" /></div></button></div></section>

        <section v-else-if="view==='library'" class="library-page"><div class="library-toolbar"><div class="device-tabs"><button :class="{active:device==='laptop'}" @click="setDevice('laptop')"><Icon name="Laptop" :size="17" /> Laptop</button><button :class="{active:device==='desktop'}" @click="setDevice('desktop')"><Icon name="Monitor" :size="17" /> PC de escritorio</button></div><span>{{ parts.length }} componentes para explorar</span></div><div class="filter-tabs" aria-label="Filtrar componentes"><button v-for="category in categories" :key="category" :class="{active:libraryFilter===category}" @click="libraryFilter=category">{{ category }}</button></div><div class="component-grid"><button v-for="c in filteredParts" :key="c.id" class="library-card" @click="searchSelect(c.id)"><div class="library-card-art" :style="{'--part-color':c.color}"><Icon :name="c.icon" :size="51" /><span>{{ c.ref }}</span><div class="component-crosshair"></div></div><div class="library-card-body"><span class="eyebrow">{{ c.category }}</span><h3>{{ c.name }}</h3><p>{{ c.summary }}</p><span class="library-card-link">Explorar en la placa <Icon name="ArrowUpRight" :size="16" /></span></div></button></div></section>

        <section v-else class="glossary-page"><div class="glossary-search"><Icon name="Search" :size="20" /><input v-model="glossarySearch" aria-label="Buscar término en el glosario" placeholder="Busca un término, por ejemplo: VCORE…" /></div><div class="glossary-grid"><article v-for="[term,definition] in matchingTerms" :key="term"><span class="glossary-mark">↗</span><h3>{{ term }}</h3><p>{{ definition }}</p></article><p v-if="!matchingTerms.length" class="empty-small">No encontramos ese término. Prueba “tensión”, “memoria” o “GND”.</p></div><div class="reference-section"><div><Icon name="Library" :size="24" /><h2>Del modelo a la documentación.</h2><p>Este laboratorio ilustra principios generales. Para trabajar en una placa real, usa el manual de servicio, el esquema de esa revisión y las hojas de datos. No todos los equipos comparten tensiones, componentes o secuencias.</p></div><div class="source-links"><a v-for="source in sources" :key="source.url" :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.title }}<Icon name="ArrowUpRight" :size="16" /></a></div></div></section>
        <footer class="page-footer"><span><Icon name="CircuitBoard" :size="14" /> PLACA LAB <span class="footer-divider">/</span> Entender es el primer paso para reparar.</span><span>{{ storageAvailable?'Tu progreso se guarda en este dispositivo':'Almacenamiento no disponible · progreso solo en esta sesión' }}<span class="tiny-dot"></span></span></footer>
      </main>
    </div>
    <LessonModal v-if="activeLesson" :key="activeLesson.id" :lesson="activeLesson" :completed="completed.includes(activeLesson.id)" @close="activeLesson=null" @complete="completeLesson" @explore="exploreLesson" />
    <dialog ref="settings" class="settings-dialog"><div class="dialog-content"><button class="icon-button close-dialog" aria-label="Cerrar preferencias" @click="settings.close()"><Icon name="X" /></button><span class="eyebrow">A TU MANERA</span><h2>Tu espacio de trabajo.</h2><div class="setting-row"><span><strong>Reducir movimiento</strong><small>Detiene el movimiento de los indicadores de energía.</small></span><button role="switch" class="switch" :class="{on:reducedMotion}" :aria-checked="reducedMotion" aria-label="Reducir movimiento" @click="reducedMotion=!reducedMotion"><span></span></button></div><div class="setting-row"><span><strong>Progreso local</strong><small>{{ completed.length }} lecciones y {{ solved.length }} casos resueltos.</small></span><button class="text-link" @click="confirmReset=true">Reiniciar</button></div><div v-if="confirmReset" class="reset-confirm"><p>Se borrará el progreso de este navegador.</p><button class="button button-outline" @click="confirmReset=false">Conservar</button><button class="button button-dark" @click="resetProgress">Reiniciar progreso</button></div><p class="help-text">No necesitas una cuenta. Las lecciones y casos se guardan únicamente en este navegador.</p></div></dialog>
    <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Icon name="CircleCheck" :size="19" />{{ toast }}<button aria-label="Cerrar aviso" @click="toast=''"><Icon name="X" :size="15" /></button></div></Transition>
  </div>
</template>
